<?php get_header(); $scenes=array(array('gateway','آرندی؛ از مسئله تا امکان','هر تحول ماندگار با شنیدن دقیق مسئله آغاز می‌شود.'),array('discover','آنچه اکنون هست را می‌بینیم','فرآیندها، داده‌ها و نقاط تصمیم را شفاف می‌کنیم.'),array('design','مسیر قابل اجرا طراحی می‌کنیم','معماری، اولویت و نقشه راه را به یک تصمیم روشن تبدیل می‌کنیم.'),array('build-secure','سامانه‌ای امن و قابل اتکا می‌سازیم','تکنولوژی زمانی ارزشمند است که در کنار تیم شما کار کند.'),array('oil-gas','صنعت را از نزدیک می‌شناسیم','برای نفت و گاز، پتروشیمی و عملیات پیچیده راهکارهای واقع‌گرا طراحی می‌کنیم.'),array('intelligence','از داده به بینش می‌رسیم','هوش مصنوعی و تحلیل داده، تصمیم‌گیری را سریع‌تر و دقیق‌تر می‌کند.'),array('finale','نتیجه، شروع یک حرکت تازه است','برای گفتگویی دربارهٔ مسئلهٔ سازمان شما آماده‌ایم.')); ?><main id="main" class="scrollwise-story"><?php foreach($scenes as $i=>$scene):$image=get_stylesheet_directory_uri().'/assets/scenes/'.$scene[0].'.webp';?><section class="scrollwise-scene" style="--scene:url('<?php echo esc_url($image);?>')"><div class="scrollwise-card"><p>ARANDI / <?php echo esc_html(sprintf('%02d',$i+1));?></p><?php if(!$i):?><h1><?php echo esc_html($scene[1]);?></h1><?php else:?><h2><?php echo esc_html($scene[1]);?></h2><?php endif;?><p><?php echo esc_html($scene[2]);?></p><?php if($i===count($scenes)-1):?><a class="scrollwise-cta" href="<?php echo esc_url(home_url('/contact/'));?>">شروع گفتگو</a><?php endif;?></div></section><?php endforeach;?></main><?php get_footer();
